 void settlements(){page("studio-settlements","Fechamentos mensais","Somente meses encerrados e ainda não revisados");get("/admin/settlements",r->{JSONArray rows=r.getJSONArray("items");if(rows.length()==0)a.empty(a.body,"chart","Nenhum mês para revisar","Mês aberto ainda não pode ser fechado para pagamento.");for(int i=0;i<rows.length();i++){JSONObject m=rows.getJSONObject(i);a.title(a.body,m.optString("creator_name","Criador")+" · "+m.optString("month").substring(0,7),18);a.text(a.body,number(m.optLong("views"))+" views · "+money(m.optDouble("gross_cents"))+" estimados",13,MUTED);a.button(a.body,"Analisar e fechar este mês",RED,()->closeMonth(m));}});}
 void closeMonth(JSONObject month){page("studio-settlement-review","Revisar fechamento",month.optString("month"));a.text(a.body,"Criador: "+month.optString("creator_id")+"\nViews: "+number(month.optLong("views"))+"\nMáximo estimado: "+money(month.optDouble("gross_cents")),14,MUTED);EditText amount=a.field(a.body,"VALOR APROVADO EM REAIS","Pode ser menor após revisão",false),reason=a.field(a.body,"PARECER DA REVISÃO","Registre os critérios e eventuais ajustes",false);amount.setText(decimal(month.optLong("gross_cents")));amount.setInputType(8194);reason.setSingleLine(false);reason.setMinLines(4);CheckBox reviewed=new CheckBox(a);reviewed.setText("Revisei as visualizações, os direitos e os sinais de irregularidade deste período.");reviewed.setTextColor(WHITE);a.body.addView(reviewed);a.button(a.body,"Conferir fechamento",RED,()->a.safe(()->{if(!reviewed.isChecked()){a.notice("Confirme que realizou a revisão antes de fechar.",true);return;}long value=cents(amount);confirm("Fechar este mês em "+money(value)+"? Esta aprovação não poderá ser duplicada.",()->post("/admin/settlements",a.obj("creator_id",month.optString("creator_id"),"month",month.optString("month"),"approved_cents",value,"reason",reason.getText().toString()),x->settlements()));}));a.button(a.body,"Consultar resultados do criador",CARD,()->{owner=month.optString("creator_id");analytics(30,0,0);});}
 void withdrawals(String status){page("studio-withdrawals-admin","Pedidos de saque","Nenhum pagamento é transferido pelo aplicativo.");HorizontalScrollView scroll=new HorizontalScrollView(a);LinearLayout filters=a.row();String[] statuses={"requested","approved","paid","rejected"},labels={"Solicitados","Aprovados","Pagos","Recusados"};for(int i=0;i<statuses.length;i++){final String value=statuses[i];a.button(filters,labels[i],value.equals(status)?RED:CARD,()->withdrawals(value));}scroll.addView(filters);a.body.addView(scroll);get("/admin/withdrawals?status="+status,r->{JSONArray rows=r.getJSONArray("items");if(rows.length()==0)a.empty(a.body,"history","Nenhum pedido neste filtro","As solicitações dos criadores aparecerão aqui.");for(int i=0;i<rows.length();i++){JSONObject w=rows.getJSONObject(i);a.title(a.body,money(w.optDouble("amount_cents"))+" · "+paymentState(w.optString("status")),18);a.text(a.body,w.optString("pix_hint")+"\n"+a.pro.date(w.optString("created_at")),12,MUTED);a.button(a.body,"Abrir solicitação",CARD,()->withdrawalDetail(w.optString("id")));}});}
 void withdrawalDetail(String id){page("studio-withdrawal-review","Conferir solicitação","Dados privados do destino de pagamento");a.getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);get("/admin/withdrawal/"+id,r->{JSONObject destination=r.getJSONObject("destination");a.title(a.body,money(r.optDouble("amount_cents")),28);a.text(a.body,paymentState(r.optString("status")),14,MUTED);a.text(a.body,"Titular: "+destination.optString("holder")+"\nTipo: "+destination.optString("type")+"\nChave: "+destination.optString("value"),15,WHITE);a.button(a.body,"Copiar chave Pix",CARD,()->copy(destination.optString("value"),true));a.text(a.body,r.optString("warning"),13,MUTED);EditText note=a.field(a.body,"PARECER OU COMPROVANTE","Informe sua decisão ou o registro do pagamento",false),reference=a.field(a.body,"REFERÊNCIA DO PAGAMENTO EXTERNO","Obrigatória ao registrar como pago",false);note.setSingleLine(false);note.setMinLines(3);if(r.optString("status").equals("requested")){a.button(a.body,"Aprovar para pagamento",RED,()->confirm("Aprovar esta solicitação? A transferência continuará manual.",()->post("/admin/withdrawals",a.obj("id",id,"status","approved","note",note.getText().toString()),x->withdrawalDetail(id))));a.button(a.body,"Recusar solicitação",CARD,()->confirm("Recusar e liberar o saldo reservado?",()->post("/admin/withdrawals",a.obj("id",id,"status","rejected","note",note.getText().toString()),x->withdrawals("rejected"))));}else if(r.optString("status").equals("approved")){CheckBox paid=new CheckBox(a);paid.setText("Conferi a titularidade e confirmei o pagamento realizado fora do aplicativo.");paid.setTextColor(WHITE);a.body.addView(paid);a.button(a.body,"Registrar como pago",RED,()->{if(!paid.isChecked()){a.notice("Confirme o pagamento externo antes de registrar.",true);return;}confirm("Registrar o pagamento já realizado?",()->post("/admin/withdrawals",a.obj("id",id,"status","paid","note",note.getText().toString(),"reference",reference.getText().toString()),x->withdrawals("paid")));});}a.button(a.body,"Histórico deste criador",BG,()->{owner=r.optString("creator_id");audit();});});}
 void observe(JSONObject show){JSONArray experiments=show.optJSONArray("experiments");if(experiments==null||experiments.length()==0||a.uid.isEmpty()||a.uid.equals(show.optString("owner_id")))return;String day=java.time.LocalDate.now(java.time.ZoneId.of("America/Sao_Paulo")).toString(),key=a.uid+":"+show.optInt("id")+":"+day+":"+experiments.toString();if(!observed.add(key))return;if(observed.size()>500)observed.clear();final String account=a.uid,viewer=a.viewerToken;a.reads.execute(()->{try{a.requestViewer.set(viewer);a.readFlow.ensureSession(account);a.request("POST","/v11/audience/impression",a.obj("show_id",show.optInt("id")),a.token);}catch(Exception ignored){observed.remove(key);}finally{a.requestViewer.remove();}});}
